// Secret redaction: a port of shapa/redact.py. The server screens every text field at write,
// whatever the client did, so a secret that reaches the hosted store is masked there too.
//
// The pattern set, the `secret` named group (only that group is masked), the split-prefix join
// and the tail absorption behave like the Python original; test/redact.test.ts replays vectors
// generated by running the Python module. Two deliberate JS-side differences, both on the
// strict side: `\b` is spelled as a Unicode word-boundary lookaround so non-ASCII letters count
// as word characters like they do in Python's `re`, and `$` is `(?=\n?$)` to keep Python's
// "end, or before a final newline" meaning.

export const PLACEHOLDER = "[REDACTED]";

const W = String.raw`\p{L}\p{N}_`; // Python's \w (Unicode)
const B_START = String.raw`(?<![${W}])`; // \b before a word character
const B_END = String.raw`(?![${W}])`; // \b after a word character

interface Pattern {
  name: string;
  /** Global clone, with indices, used to rewrite. */
  re: RegExp;
  /** Non-global clone, used to test (no lastIndex state). */
  test: RegExp;
}

function pattern(name: string, source: string, flags = ""): Pattern {
  return {
    name,
    re: new RegExp(source, `${flags}gdu`),
    test: new RegExp(source, `${flags}u`),
  };
}

export const PATTERNS: readonly Pattern[] = [
  pattern(
    "pem-private-key",
    String.raw`-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?(?:-----END [A-Z0-9 ]*PRIVATE KEY-----|(?=\n?$))`,
  ),
  pattern("anthropic-key", String.raw`${B_START}sk-ant-[A-Za-z0-9_-]{10,}`),
  pattern("openai-key", String.raw`${B_START}sk-(?:proj-|svcacct-|admin-)?[A-Za-z0-9_-]{20,}`),
  pattern("stripe-key", String.raw`${B_START}(?:sk|rk|pk)_(?:live|test)_[A-Za-z0-9]{10,}`),
  pattern("stripe-webhook", String.raw`${B_START}whsec_[A-Za-z0-9]{10,}`),
  pattern(
    "github-token",
    String.raw`${B_START}(?:ghp|gho|ghs|ghr|ghu)_[A-Za-z0-9]{20,}|${B_START}github_pat_[A-Za-z0-9_]{20,}`,
  ),
  pattern("gitlab-token", String.raw`${B_START}glpat-[A-Za-z0-9_-]{20,}`),
  pattern("slack-token", String.raw`${B_START}xox[abposr]-[A-Za-z0-9-]{10,}`),
  pattern("aws-access-key", String.raw`${B_START}(?:AKIA|ASIA)[A-Z0-9]{16}${B_END}`),
  pattern("google-api-key", String.raw`${B_START}AIza[0-9A-Za-z_-]{35}`),
  pattern("huggingface-token", String.raw`${B_START}hf_[A-Za-z0-9]{30,}`),
  pattern("npm-token", String.raw`${B_START}npm_[A-Za-z0-9]{36}`),
  pattern("supabase-key", String.raw`${B_START}sb_(?:secret|publishable)_[A-Za-z0-9_-]{10,}`),
  pattern("resend-key", String.raw`${B_START}re_[A-Za-z0-9]{20,}`),
  pattern(
    "jwt",
    String.raw`${B_START}eyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}`,
  ),
  pattern(
    "url-password",
    String.raw`${B_START}[a-z][a-z0-9+.-]{1,20}://[^\s:/?#@]+:(?<secret>[^\s@/]{3,})@`,
    "i",
  ),
  pattern("bearer", String.raw`${B_START}Bearer\s+(?<secret>[A-Za-z0-9._~+/=-]{10,})`),
  pattern("basic-auth", String.raw`${B_START}Basic\s+(?<secret>[A-Za-z0-9+/=]{16,})`),
  // KEY=value / "token": "value" / password: value - the name must look like a credential and
  // the value must be a single unbroken run (prose such as "token: none of these apply" stays).
  pattern(
    "credential-assignment",
    String.raw`${B_START}[${W}.-]*(?:api[_-]?key|secret|token|passw(?:or)?d|passwd|pwd|access[_-]?key|` +
      String.raw`private[_-]?key|client[_-]?secret)[${W}.-]*["']?\s*[:=]\s*["']?` +
      String.raw`(?<secret>[A-Za-z0-9+/_=.~-]{12,})`,
    "i",
  ),
  pattern(
    "conn-string-password",
    String.raw`${B_START}(?:password|pwd)\s*=\s*(?<secret>[^;\s"']{6,})`,
    "i",
  ),
];

/** A token that starts like a known key prefix but may have been cut by a line wrap, and the
 * whitespace-separated run that follows it. */
const PREFIX_SPLIT = new RegExp(
  String.raw`(?<![A-Za-z0-9_-])((?:sk-|rk_|pk_|whsec_|gh[opsru]_|github_pat_|glpat-|xox[abposr]-|AKIA|ASIA|` +
    String.raw`AIza|hf_|npm_|sb_|re_|eyJ)[A-Za-z0-9_.-]*)(\s+)([A-Za-z0-9_+/=.-]{4,})`,
  "gu",
);

/** Key-shaped runs right after a redaction: the rest of a secret that a line wrap split off. */
const TAIL = new RegExp(
  String.raw`\[REDACTED\](?:\s+(?:(?=[A-Za-z_+/=.-]*[0-9])[A-Za-z0-9_+/=.-]{6,}|[A-Za-z0-9_+/=.-]{20,}))+`,
  "gu",
);

function matchesAny(text: string): boolean {
  return PATTERNS.some((p) => p.test.test(text));
}

function joinSplitPrefixes(input: string): string {
  let text = input;
  for (let i = 0; i < 4; i++) {
    const joined = text.replace(PREFIX_SPLIT, (whole, head: string, _ws: string, tail: string) =>
      !matchesAny(head) && matchesAny(head + tail) ? head + tail : whole,
    );
    if (joined === text) break;
    text = joined;
  }
  return text;
}

/** Replace every match of `p` in `text`; a `secret` group masks only itself. */
function substitute(p: Pattern, text: string): [string, number] {
  let out = "";
  let last = 0;
  let hits = 0;
  for (const m of text.matchAll(p.re)) {
    hits += 1;
    const start = m.index;
    const end = start + m[0].length;
    out += text.slice(last, start);
    const span = m.indices?.groups?.["secret"];
    if (span) out += text.slice(start, span[0]) + PLACEHOLDER + text.slice(span[1], end);
    else out += PLACEHOLDER;
    last = end;
  }
  return hits ? [out + text.slice(last), hits] : [text, 0];
}

/** `[redacted_text, hits]`. Idempotent: the placeholder never matches a pattern. */
export function scrub(text: string): [string, number] {
  if (!text) return [text, 0];
  let hits = 0;
  let out = joinSplitPrefixes(text);
  for (const p of PATTERNS) {
    const [next, n] = substitute(p, out);
    out = next;
    hits += n;
  }
  if (hits) out = out.replace(TAIL, PLACEHOLDER);
  return [out, hits];
}

export function redact(text: string): string {
  return scrub(text)[0];
}
